    37→/**
    38→ * Circle packings of shapes, subject to varying constraints and patterns of
    39→ * tangencies.
    40→ * <p>
    41→ * Each method produces a circle packing with different characteristics using a
    42→ * different technique; for this reason input arguments vary across the methods.
    43→ * <p>
    44→ * The output of each method is a list of PVectors, each representing one
    45→ * circle: (.x, .y) represent the center point and .z represents radius.
    46→ * <p>
    47→ * Where applicable, packings will include circles that overlap with the shape,
    48→ * rather than only including those circles whose center point lies inside the
    49→ * shape.
    50→ * 
    51→ * @author Michael Carleton
    52→ * @since 1.1.0
    53→ *
    54→ */
    55→public final class PGS_CirclePacking {
    56→
    57→	/*-
    58→	 * Roadmap (see/implement): 'A LINEARIZED CIRCLE PACKING ALGORITHM'? 
    59→	 * 'A note on circle packing' Young Joon AHN.
    60→	 */
    61→
    62→	private PGS_CirclePacking() {
    63→	}
    64→
    65→	/**
    66→	 * Packs circles of varying radii within a given shape, whilst respecting
    67→	 * pointal obstacles using the Largest Empty Circle (LEC) algorithm. The method
    68→	 * continues to generate circles until the sum of the areas of the circles
    69→	 * exceeds a specified proportion of the area of the given shape.
    70→	 * 
    71→	 * @param shape          The shape within which circles will be packed. The
    72→	 *                       shape should be in the form of PShape.
    73→	 * @param pointObstacles A collection of PVector points representing obstacles,
    74→	 *                       around which circles are packed. Only points contained
    75→	 *                       within the shape are relevant.
    76→	 * @param areaCoverRatio The target ratio of the total area of the circles to
    77→	 *                       the area of the shape. This parameter should be a
    78→	 *                       double between 0 and 1. Circle generation will stop
    79→	 *                       when this ratio is reached.
    80→	 * @return A list of PVectors, where each PVector represents a circle. The x and
    81→	 *         y components of the PVector represent the center of the circle, and
    82→	 *         the z component represents the radius of the circle.
    83→	 * @since 1.3.1
    84→	 */
    85→	public static List<PVector> obstaclePack(PShape shape, Collection<PVector> pointObstacles, double areaCoverRatio) {
    86→		final Geometry geometry = fromPShape(shape);
    87→
    88→		LargestEmptyCircles lec = new LargestEmptyCircles(fromPShape(PGS_Conversion.toPointsPShape(pointObstacles)), geometry,
    89→				areaCoverRatio > 0.95 ? 0.5 : 1);
    90→
    91→		final double shapeArea = geometry.getArea();
    92→		double circlesArea = 0;
    93→		List<PVector> circles = new ArrayList<>();
    94→
    95→		while (circlesArea / shapeArea < areaCoverRatio) {
    96→			double[] currentLEC = lec.findNextLEC();
    97→			circles.add(new PVector((float) currentLEC[0], (float) currentLEC[1], (float) currentLEC[2]));
    98→			circlesArea += Math.PI * currentLEC[2] * currentLEC[2];
    99→			if (currentLEC[2] < 0.5) {
   100→				break;
   101→			}
   102→		}
   103→		return circles;
   104→	}
   105→
   106→	/**
   107→	 * Generates a circle packing of the input shape, using the inscribed circles
   108→	 * (or incircles) of triangles from a triangulation of the shape.
   109→	 * <p>
   110→	 * Circles in this packing do not overlap and are contained entirely within the
   111→	 * shape. However, not every circle is necessarily tangent to others.
   112→	 * 
   113→	 * @param shape       the shape from which to generate a circle packing
   114→	 * @param points      the number of random points to insert into the
   115→	 *                    triangulation as steiner points. Larger values lead to
   116→	 *                    more circles that are generally smaller.
   117→	 * @param refinements number of times to refine the underlying triangulation.
   118→	 *                    Larger values lead to more circles that are more regularly
   119→	 *                    spaced and sized. 0...3 is a suitable range for this
   120→	 *                    parameter
   121→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   122→	 *         the center point and .z represents radius.
   123→	 */
   124→	public static List<PVector> trinscribedPack(PShape shape, int points, int refinements) {
   125→		final List<PVector> steinerPoints = PGS_Processing.generateRandomPoints(shape, points);
   126→		final IIncrementalTin tin = PGS_Triangulation.delaunayTriangulationMesh(shape, steinerPoints, true, refinements, true);
   127→		return StreamSupport.stream(tin.triangles().spliterator(), false).filter(filterBorderTriangles).map(t -> inCircle(t))
   128→				.collect(Collectors.toList());
   129→	}
   130→
   131→	/**
   132→	 * Generates a random circle packing of the input shape by generating random
   133→	 * points one-by-one and calculating the maximum radius a circle at each point
   134→	 * can have (such that it's tangent to its nearest circle or a shape vertex).
   135→	 * <p>
   136→	 * Notably, the {@code points} argument defines the number of random point
   137→	 * attempts (or circle attempts), and not the number of circles in the final
   138→	 * packing output, since a point is rejected if it lies in an existing circle or
   139→	 * whose nearest circle is less than minRadius distance away. In other words,
   140→	 * {@code points} defines the maximum number of circles the packing can have; in
   141→	 * practice, the packing will contain somewhat fewer circles.
   142→	 * <p>
   143→	 * Circles in this packing do not overlap and are contained entirely within the
   144→	 * shape. However, not every circle is necessarily tangent to other circles (in
   145→	 * which case, such a circle will be tangent to a shape vertex).
   146→	 * 
   147→	 * @param shape             the shape from which to generate a circle packing
   148→	 * @param points            number of random points to generate (this is not the
   149→	 *                          number of circles in the packing).
   150→	 * @param minRadius         filter (however not simply applied at the end, so
   151→	 *                          affects how the packing operates during packing)
   152→	 * @param triangulatePoints when true, triangulates an initial random point set
   153→	 *                          and uses triangle centroids as the random point set
   154→	 *                          instead; this results in a packing that covers the
   155→	 *                          shape more evenly (particularly when points is
   156→	 *                          small), which is sometimes desirable
   157→	 * @return A list of PVectors, each representing one circle: (.x, .y) represent
   158→	 *         the center point and .z represents radius.
   159→	 */
